"""Screener 2026-11-05: recent cross-sectional IC sanity check on library factors.

Data through last completed trading day 2026-11-04 (visible_through).
Implements each factor exactly as in strategy.py. Computes daily cross-sectional
rank IC at 10d forward horizon, plus ICIR, hit rate, and factor correlation.
"""
import json, math
import numpy as np
import pandas as pd

DATA = "../persistent/stock_data"
IDX = "../persistent/index_data"
END = "2026-11-04"
ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
          "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]


def load_closes(sym):
    df = pd.read_csv(f"{DATA}/{sym}.csv")
    df["date"] = pd.to_datetime(df["date"])
    df = df[df["date"] <= END].set_index("date")["close"].astype(float)
    return df


def trend_r2(c):
    s = c.dropna().tail(30)
    if len(s) < 18:
        return None
    y = np.log(s.values.astype(float))
    x = np.arange(len(y))
    cov = float(np.cov(y, x)[0, 1])
    vy, vx = float(np.var(y)), float(np.var(x))
    if vy <= 0 or vx <= 0:
        return None
    return math.copysign(cov * cov / (vy * vx), cov)


def semi_down_ratio(r):
    s = r.dropna().tail(20)
    if len(s) < 10:
        return None
    down = float((s.clip(upper=0) ** 2).mean() ** 0.5)
    up = float((s.clip(lower=0) ** 2).mean() ** 0.5)
    if up < 1e-12:
        return None
    return down / up - 1.0


def mom_120(c):
    if len(c) < 126:
        return None
    p0 = float(c.iloc[-126])
    if p0 <= 0:
        return None
    return float(c.iloc[-6]) / p0 - 1.0


def underwater(c):
    s = c.dropna().tail(125)
    if len(s) < 60:
        return None
    w = s.tail(120).values.astype(float)
    roll = np.maximum.accumulate(w)
    mask = w == roll
    idx = np.flatnonzero(mask)
    return float(len(w) - 1 - idx[-1]) if len(idx) else float(len(w))


def vol_of_vol(r):
    s = r.dropna().tail(120)
    if len(s) < 90:
        return None
    v = s.rolling(20).std()
    out = v.rolling(60).std().iloc[-1]
    return None if not math.isfinite(out) else float(out)


def kurt_20(r):
    s = r.dropna().tail(40)
    if len(s) < 20:
        return None
    k = s.rolling(20, min_periods=8).kurt().iloc[-1]
    return None if not math.isfinite(k) else float(k)


def dxy_beta(r, dxy_r):
    z = pd.concat([r.rename("a"), dxy_r.rename("d")], axis=1).dropna().tail(60)
    if len(z) < 30:
        return None
    vd = float(z["d"].var())
    if vd < 1e-14:
        return None
    return float(z["a"].cov(z["d"]) / vd)


# ---- build panels ----
panel = pd.DataFrame({a: load_closes(a) for a in ASSETS}).sort_index()
rets = panel.pct_change()

dxy = pd.read_csv(f"{IDX}/DXY.csv")
dxy["date"] = pd.to_datetime(dxy["date"])
dxy = dxy[dxy["date"] <= END].set_index("date")["close"].astype(float)
dxy_r = dxy.pct_change()

vix = pd.read_csv(f"{IDX}/VIX.csv")
vix["date"] = pd.to_datetime(vix["date"])
vix = vix[vix["date"] <= END].set_index("date")["close"].astype(float)

# ---- factor time series (expanding windows over the panel) ----
def factor_panel(fn, needs_dxy=False):
    out = {}
    for a in ASSETS:
        c = panel[a]
        r = rets[a]
        vals = {}
        for dt in panel.index:
            cc = c.loc[:dt]
            rr = r.loc[:dt]
            try:
                if needs_dxy:
                    v = fn(rr, dxy_r.loc[:dt])
                else:
                    v = fn(cc) if fn in (trend_r2, mom_120, underwater) else fn(rr)
            except Exception:
                v = None
            vals[dt] = v
        out[a] = pd.Series(vals)
    return pd.DataFrame(out)


FACTORS = {
    "trend_r2_30_signed": (trend_r2, 1, False),
    "semi_down_ratio_20": (semi_down_ratio, -1, False),
    "mom_120d_skip5": (mom_120, 1, False),
    "vol_of_vol20x60": (vol_of_vol, 1, False),
    "dxy_beta_60": (dxy_beta, 1, True),
    "time_under_water_120": (underwater, -1, False),
    "kurt_20": (kurt_20, 1, False),
    "mom_10d_skip5": (lambda c: None, 1, False),   # placeholder replaced below
    "vix_beta_cond_60x20": (lambda c: None, -1, False),
    "WTI_BETA_60": (lambda c: None, 1, False),
}


def mom_10(c):
    if len(c) < 16:
        return None
    p0 = float(c.iloc[-16])
    if p0 <= 0:
        return None
    return float(c.iloc[-6]) / p0 - 1.0


def vix_beta(r, vix_r):
    z = pd.concat([r.rename("a"), vix_r.rename("v")], axis=1).dropna().tail(60)
    if len(z) < 30:
        return None
    vv = float(z["v"].var())
    if vv < 1e-14:
        return None
    return float(z["a"].cov(z["v"]) / vv)


def wti_beta(r, wti_r):
    z = pd.concat([r.rename("a"), wti_r.rename("w")], axis=1).dropna().tail(60)
    if len(z) < 30:
        return None
    vw = float(z["w"].var())
    if vw < 1e-14:
        return None
    return float(z["a"].cov(z["w"]) / vw)


# mom_10d_skip5 (10d return skipping last 5d)
mp = {}
for a in ASSETS:
    c = panel[a]
    mp[a] = pd.Series({dt: mom_10(c.loc[:dt]) for dt in panel.index})
FACTORS["mom_10d_skip5"] = (lambda c: None, 1, False)
factor_values = {"mom_10d_skip5": pd.DataFrame(mp)}

wti = load_closes("WTI")
wti_r_full = wti.pct_change()
vb = {}
for a in ASSETS:
    r = rets[a]
    vb[a] = pd.Series({dt: vix_beta(r.loc[:dt], vix.loc[:dt].pct_change()) for dt in panel.index})
factor_values["vix_beta_cond_60x20"] = pd.DataFrame(vb)

wb = {}
for a in ASSETS:
    r = rets[a]
    wb[a] = pd.Series({dt: wti_beta(r.loc[:dt], wti_r_full.loc[:dt]) for dt in panel.index})
factor_values["WTI_BETA_60"] = pd.DataFrame(wb)

for fid, (fn, _, needs_dxy) in FACTORS.items():
    if fid in factor_values:
        continue
    factor_values[fid] = factor_panel(fn, needs_dxy)

fwd = panel.shift(-10) / panel - 1.0  # 10d forward return (t -> t+10)

# ---- IC stats ----
def ic_stats(fvals, fwd_ret, start):
    sub_f = fvals.loc[start:]
    sub_r = fwd_ret.loc[start:]
    ics = []
    for dt in sub_f.index:
        x = sub_f.loc[dt].dropna()
        y = sub_r.loc[dt].reindex(x.index).dropna()
        if len(x) >= 8 and len(y) >= 8:
            ic = x.rank().corr(y.rank())
            if math.isfinite(ic):
                ics.append(ic)
    ics = np.array(ics)
    if len(ics) == 0:
        return None
    ic_m = ics.mean()
    icir = ic_m / (ics.std(ddof=1) / math.sqrt(len(ics))) if ics.std(ddof=1) > 0 else 0.0
    hit = float((ics > 0).mean())
    return {"n": len(ics), "ic": ic_m, "icir": icir, "hit": hit}

print(f"{'factor':24s} | {'lib dir':>4s} | {'120d ic/icir/hit':>22s} | {'60d ic/icir/hit':>22s} | {'30d ic':>8s}")
rows = []
for fid, (_, direction, _) in FACTORS.items():
    fv = factor_values[fid]
    r120 = ic_stats(fv, fwd, panel.index[-120])
    r60 = ic_stats(fv, fwd, panel.index[-60])
    r30 = ic_stats(fv, fwd, panel.index[-30])
    def fmt(r):
        if r is None:
            return "  n/a  "
        return f"{r['ic']:+.3f}/{r['icir']:+.2f}/{r['hit']:.2f}"
    print(f"{fid:24s} | {direction:>4d} | {fmt(r120):>22s} | {fmt(r60):>22s} | {r30['ic'] if r30 else float('nan'):+.3f}")
    rows.append((fid, direction, r120, r60, r30))

# ---- recent factor correlation (last 60d, cross-sectional spearman per date averaged) ----
print("\nRecent 60d avg cross-sectional |spearman| correlation matrix:")
fids = list(FACTORS.keys())
corr_mat = pd.DataFrame(np.eye(len(fids)), index=fids, columns=fids)
dates = panel.index[-60:]
for i, f1 in enumerate(fids):
    for j, f2 in enumerate(fids):
        if j <= i:
            continue
        cs = []
        for dt in dates:
            x = factor_values[f1].loc[dt].dropna()
            y = factor_values[f2].loc[dt].reindex(x.index).dropna()
            if len(x) >= 8:
                c = x.rank().corr(y.rank())
                if math.isfinite(c):
                    cs.append(c)
        if cs:
            corr_mat.loc[f1, f2] = corr_mat.loc[f2, f1] = float(np.mean(cs))
print(corr_mat.round(2).to_string())

# ---- latest factor snapshot (last date) ----
print("\nLatest factor snapshot (2026-11-04):")
for fid in fids:
    fv = factor_values[fid]
    last = fv.iloc[-1].dropna()
    print(f"  {fid:24s} valid={len(last):2d}  top3={list(last.nlargest(3).index)}  bot3={list(last.nsmallest(3).index)}")

json.dump({fid: {"dir": d, "ic120": (r120 and r120["ic"]), "icir120": (r120 and r120["icir"]),
                 "ic60": (r60 and r60["ic"]), "icir60": (r60 and r60["icir"]),
                 "ic30": (r30 and r30["ic"])}
           for fid, d, r120, r60, r30 in rows},
          open("scripts/screener_20261105_ic_results.json", "w"), indent=1)
print("\nsaved scripts/screener_20261105_ic_results.json")

